use std::io::Write;
use std::process::{Command, Stdio};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Lit {
    pub var: usize,
    pub negated: bool,
}

impl Lit {
    pub fn pos(var: usize) -> Self {
        Self { var, negated: false }
    }

    pub fn neg(var: usize) -> Self {
        Self { var, negated: true }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Cnf {
    pub num_vars: usize,
    pub clauses: Vec<Vec<Lit>>,
}

impl Cnf {
    pub fn new(num_vars: usize) -> Self {
        Self {
            num_vars,
            clauses: Vec::new(),
        }
    }

    pub fn add_clause(&mut self, clause: Vec<Lit>) {
        self.clauses.push(clause);
    }
}

/// Solve CNF with a mature backend first (`z3` CLI), then fallback to local DPLL.
pub fn solve(cnf: &Cnf) -> Option<Vec<bool>> {
    solve_with_z3_cli(cnf).or_else(|| solve_with_dpll(cnf))
}

pub fn is_partial_consistent(cnf: &Cnf, assignment: &[Option<bool>]) -> bool {
    cnf.clauses.iter().all(|clause| {
        let mut has_true = false;
        let mut has_unassigned = false;
        for lit in clause {
            match assignment.get(lit.var).and_then(|v| *v) {
                Some(value) => {
                    let lit_value = if lit.negated { !value } else { value };
                    if lit_value {
                        has_true = true;
                        break;
                    }
                }
                None => has_unassigned = true,
            }
        }
        has_true || has_unassigned
    })
}

fn solve_with_dpll(cnf: &Cnf) -> Option<Vec<bool>> {
    let mut assignment: Vec<Option<bool>> = vec![None; cnf.num_vars];
    if dpll(cnf, &mut assignment) {
        Some(assignment.into_iter().map(|v| v.unwrap_or(false)).collect())
    } else {
        None
    }
}

fn dpll(cnf: &Cnf, assignment: &mut [Option<bool>]) -> bool {
    if !is_partial_consistent(cnf, assignment) {
        return false;
    }
    if assignment.iter().all(Option::is_some) {
        return true;
    }

    let var = assignment
        .iter()
        .position(|v| v.is_none())
        .expect("some variable must be unassigned");

    assignment[var] = Some(true);
    if dpll(cnf, assignment) {
        return true;
    }

    assignment[var] = Some(false);
    if dpll(cnf, assignment) {
        return true;
    }

    assignment[var] = None;
    false
}

fn solve_with_z3_cli(cnf: &Cnf) -> Option<Vec<bool>> {
    let mut child = Command::new("z3")
        .args(["-in", "-smt2"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .ok()?;

    {
        let stdin = child.stdin.as_mut()?;
        stdin.write_all(build_smt2(cnf).as_bytes()).ok()?;
    }

    let out = child.wait_with_output().ok()?;
    if !out.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    parse_z3_model(&text, cnf.num_vars)
}

fn build_smt2(cnf: &Cnf) -> String {
    let mut s = String::new();
    s.push_str("(set-logic QF_BOOL)\n");
    for i in 0..cnf.num_vars {
        s.push_str(&format!("(declare-fun x{i} () Bool)\n"));
    }
    for clause in &cnf.clauses {
        if clause.is_empty() {
            s.push_str("(assert false)\n");
            continue;
        }
        s.push_str("(assert (or");
        for lit in clause {
            if lit.negated {
                s.push_str(&format!(" (not x{})", lit.var));
            } else {
                s.push_str(&format!(" x{}", lit.var));
            }
        }
        s.push_str("))\n");
    }
    s.push_str("(check-sat)\n(get-model)\n");
    s
}

fn parse_z3_model(out: &str, num_vars: usize) -> Option<Vec<bool>> {
    let mut lines = out.lines();
    let status = lines.next()?.trim();
    if status == "unsat" {
        return None;
    }
    if status != "sat" {
        return None;
    }

    let mut model = vec![false; num_vars];
    let all = out.replace('\n', " ");
    for (i, slot) in model.iter_mut().enumerate().take(num_vars) {
        let needle = format!("(define-fun x{i} () Bool ");
        if let Some(pos) = all.find(&needle) {
            let rest = &all[pos + needle.len()..];
            *slot = rest.starts_with("true");
        }
    }
    Some(model)
}

use crate::data_structures::union_find::UnionFind;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct EqualityConstraint {
    pub left: u32,
    pub right: u32,
}

impl EqualityConstraint {
    pub fn new(left: u32, right: u32) -> Self {
        Self { left, right }
    }
}

pub fn solve_constraints_cpu(var_count: usize, constraints: &[EqualityConstraint]) -> Result<Vec<u32>, String> {
    validate_constraints(var_count, constraints)?;
    let mut uf = UnionFind::new(var_count);
    for c in constraints {
        uf.union(c.left as usize, c.right as usize);
    }
    Ok(uf.labels().into_iter().map(|x| x as u32).collect())
}

#[cfg(feature = "cuda")]
unsafe extern "C" {
    fn gpu_union_find_solve(var_count: i32, edge_count: i32, edge_u: *const i32, edge_v: *const i32, parent_out: *mut i32) -> i32;
}

#[cfg(feature = "cuda")]
pub fn solve_constraints_gpu(var_count: usize, constraints: &[EqualityConstraint]) -> Result<Vec<u32>, String> {
    validate_constraints(var_count, constraints)?;

    let mut edge_u = Vec::with_capacity(constraints.len());
    let mut edge_v = Vec::with_capacity(constraints.len());
    for c in constraints {
        edge_u.push(c.left as i32);
        edge_v.push(c.right as i32);
    }

    let mut parents = vec![-1i32; var_count];
    let ok = unsafe {
        gpu_union_find_solve(
            var_count as i32,
            constraints.len() as i32,
            edge_u.as_ptr(),
            edge_v.as_ptr(),
            parents.as_mut_ptr(),
        )
    };

    if ok == 0 {
        return Err("gpu_union_find_solve failed".into());
    }

    normalize_parent_roots(&mut parents);
    Ok(parents.into_iter().map(|p| p as u32).collect())
}

pub fn solve_constraints_auto(var_count: usize, constraints: &[EqualityConstraint]) -> Result<Vec<u32>, String> {
    #[cfg(feature = "cuda")]
    {
        if let Ok(out) = solve_constraints_gpu(var_count, constraints) {
            return Ok(out);
        }
    }

    solve_constraints_cpu(var_count, constraints)
}

fn validate_constraints(var_count: usize, constraints: &[EqualityConstraint]) -> Result<(), String> {
    for (i, c) in constraints.iter().enumerate() {
        if c.left as usize >= var_count || c.right as usize >= var_count {
            return Err(format!("constraint {i} out of range: ({}, {}) with var_count={var_count}", c.left, c.right));
        }
    }
    Ok(())
}

fn normalize_parent_roots(parents: &mut [i32]) {
    for i in 0..parents.len() {
        if parents[i] < 0 {
            parents[i] = i as i32;
        }
    }

    for i in 0..parents.len() {
        let mut x = i;
        while (parents[x] as usize) != x {
            x = parents[x] as usize;
        }
        let root = x as i32;

        let mut y = i;
        while (parents[y] as usize) != y {
            let next = parents[y] as usize;
            parents[y] = root;
            y = next;
        }
        parents[i] = root;
    }
}

