//! CFG structural pattern matching.
//!
//! Variables:
//!   blocks : &[BasicBlock]  — flat CFG block list
//!   adj    : &[Vec<usize>]  — CFG successor adjacency
//!
//! Equations:
//!   iterator_loop(b) = true iff b contains a SwitchInt on Option discriminant
//!     with one arm mapping to a loop-body block and one to a loop-exit block
//!
//!   for_loop_pattern:
//!     loop_head   -> call .next() -> store result
//!     switch_head -> SwitchInt(discriminant) -> [exit_arm, body_arm]
//!     body_arm    -> loop body blocks -> goto loop_head
//!     exit_arm    -> post-loop continuation
//!
//! Used by: canon-capture analyze_switch_structure to recognize iterator patterns.

use std::collections::HashSet;

/// Describes a detected iterator for-loop in the CFG.
#[derive(Debug, Clone)]
pub struct IteratorLoopPattern {
    /// Block that calls `.next()` and holds the Option result.
    pub loop_head: usize,
    /// Block containing the SwitchInt on the Option discriminant.
    pub switch_block: usize,
    /// Block index of the Some arm (loop body entry).
    pub body_entry: usize,
    /// Block index of the None arm (loop exit).
    pub exit_block: usize,
    /// All blocks belonging to the loop body (reachable from body_entry, not through exit).
    pub body_blocks: HashSet<usize>,
}

/// Detect iterator for-loop patterns in a CFG.
///
/// A switch block is an iterator loop switch iff:
///   - it has exactly 2 successors
///   - one successor (exit) has no back-edge to the switch block's predecessor chain
///   - the other successor (body) eventually reaches a block that jumps back to loop_head
///
/// Returns one entry per detected loop.
pub fn detect_iterator_loops(adj: &[Vec<usize>], back_edges: &HashSet<(usize, usize)>) -> Vec<IteratorLoopPattern> {
    let n = adj.len();
    let mut patterns = Vec::new();

    for switch_block in 0..n {
        let succs = &adj[switch_block];
        if succs.len() != 2 {
            continue;
        }
        let (s0, s1) = (succs[0], succs[1]);

        // Determine which successor is the loop body vs exit by back-edge presence.
        // The body successor should have a back-edge somewhere in its reachable set.
        let s0_has_back = reachable_has_back_edge(s0, adj, back_edges, switch_block);
        let s1_has_back = reachable_has_back_edge(s1, adj, back_edges, switch_block);

        let (body_entry, exit_block) = match (s0_has_back, s1_has_back) {
            (true, false) => (s0, s1),
            (false, true) => (s1, s0),
            _ => continue, // ambiguous or not a loop
        };

        // Find loop_head: the predecessor of switch_block that is the .next() call site.
        // In practice this is the immediate dominator of switch_block within the loop.
        let loop_head = find_loop_head(switch_block, adj, back_edges);

        // Collect all body blocks: reachable from body_entry without crossing exit_block.
        let body_blocks = collect_body_blocks(body_entry, adj, exit_block, switch_block);

        patterns.push(IteratorLoopPattern { loop_head, switch_block, body_entry, exit_block, body_blocks });
    }
    patterns
}

/// Compute back edges in the CFG using DFS.
/// A back edge (u, v) means v is an ancestor of u in the DFS tree.
pub fn compute_back_edges(adj: &[Vec<usize>]) -> HashSet<(usize, usize)> {
    let n = adj.len();
    let mut visited = vec![false; n];
    let mut on_stack = vec![false; n];
    let mut back_edges = HashSet::new();
    for start in 0..n {
        if !visited[start] {
            dfs_back_edges(start, adj, &mut visited, &mut on_stack, &mut back_edges);
        }
    }
    back_edges
}

fn dfs_back_edges(u: usize, adj: &[Vec<usize>], visited: &mut Vec<bool>, on_stack: &mut Vec<bool>, back_edges: &mut HashSet<(usize, usize)>) {
    visited[u] = true;
    on_stack[u] = true;
    for &v in &adj[u] {
        if v >= adj.len() {
            continue;
        }
        if !visited[v] {
            dfs_back_edges(v, adj, visited, on_stack, back_edges);
        } else if on_stack[v] {
            back_edges.insert((u, v));
        }
    }
    on_stack[u] = false;
}

fn reachable_has_back_edge(start: usize, adj: &[Vec<usize>], back_edges: &HashSet<(usize, usize)>, stop_at: usize) -> bool {
    let n = adj.len();
    let mut visited = vec![false; n];
    let mut stack = vec![start];
    while let Some(u) = stack.pop() {
        if u == stop_at || visited[u] {
            continue;
        }
        visited[u] = true;
        for &v in &adj[u] {
            if v < n {
                if back_edges.contains(&(u, v)) {
                    return true;
                }
                stack.push(v);
            }
        }
    }
    false
}

fn find_loop_head(switch_block: usize, adj: &[Vec<usize>], back_edges: &HashSet<(usize, usize)>) -> usize {
    // Loop head is the target of any back-edge that reaches switch_block.
    for &(src, dst) in back_edges {
        if dst <= switch_block && src >= switch_block {
            return dst;
        }
    }
    switch_block
}

fn collect_body_blocks(entry: usize, adj: &[Vec<usize>], exit_block: usize, switch_block: usize) -> HashSet<usize> {
    let n = adj.len();
    let mut visited = HashSet::new();
    let mut stack = vec![entry];
    while let Some(u) = stack.pop() {
        if u == exit_block || u == switch_block || visited.contains(&u) {
            continue;
        }
        visited.insert(u);
        for &v in &adj[u] {
            if v < n {
                stack.push(v);
            }
        }
    }
    visited
}

//! Reaching definitions (forward dataflow).

use std::collections::{HashMap, HashSet};

pub type DefId = String;
pub type BlockId = usize;

pub struct DataflowFacts {
    pub r#gen: HashMap<BlockId, HashSet<DefId>>,
    pub kill: HashMap<BlockId, HashSet<DefId>>,
}

pub struct DataflowResult {
    pub r#in: HashMap<BlockId, HashSet<DefId>>,
    pub out: HashMap<BlockId, HashSet<DefId>>,
}

pub fn reaching_definitions(blocks: &[BlockId], pred: &HashMap<BlockId, Vec<BlockId>>, facts: &DataflowFacts) -> DataflowResult {
    let mut r#in: HashMap<BlockId, HashSet<DefId>> = HashMap::new();
    let mut out: HashMap<BlockId, HashSet<DefId>> = HashMap::new();
    for &b in blocks {
        r#in.insert(b, HashSet::new());
        out.insert(b, facts.r#gen.get(&b).cloned().unwrap_or_default());
    }
    let mut changed = true;
    while changed {
        changed = false;
        for &b in blocks {
            let new_in: HashSet<DefId> = pred.get(&b).map(|ps| ps.iter().flat_map(|p| out[p].iter().cloned()).collect()).unwrap_or_default();
            let kill = facts.kill.get(&b).cloned().unwrap_or_default();
            let r#gen = facts.r#gen.get(&b).cloned().unwrap_or_default();
            let new_out: HashSet<DefId> = r#gen.union(&new_in.difference(&kill).cloned().collect::<HashSet<_>>()).cloned().collect();
            if new_out != out[&b] {
                out.insert(b, new_out);
                changed = true;
            }
            r#in.insert(b, new_in);
        }
    }
    DataflowResult { r#in, out }
}

//! Iterative dominator computation over a control-flow graph.

use std::collections::{HashMap, HashSet};

/// Post-dominator computation.
///
/// Variables:
///   node_count : usize              — number of real blocks
///   succs      : &[Vec<usize>]      — forward adjacency (succs[v] = successors)
///   exit_nodes : &[usize]           — blocks whose Terminator is Return
///
/// Equations:
///   G_rev : reverse all edges of the forward CFG
///   super_exit = node_count        (synthetic node index)
///   G_rev edges from super_exit -> each exit_node
///   post_dom[v] = dom(G_rev, super_exit)[v]
///
/// Returns post_dom[v] = immediate post-dominator index for each real block v.
/// super_exit node (index node_count) is included in returned vec but can be ignored.
pub fn post_dominators(node_count: usize, succs: &[Vec<usize>], exit_nodes: &[usize]) -> Vec<HashSet<usize>> {
    let total = node_count + 1; // +1 for synthetic super_exit
    let super_exit = node_count;

    // Build reversed predecessor map for the iterative dominator algorithm.
    // In reversed graph: edges go dst->src for every src->dst in forward graph.
    // super_exit -> each real exit block.
    let mut preds: HashMap<usize, Vec<usize>> = HashMap::new();
    for v in 0..node_count {
        let nbrs = succs.get(v).map(|s| s.as_slice()).unwrap_or(&[]);
        for &w in nbrs {
            // forward edge v->w  =>  reversed edge w->v, so w has pred v in rev graph
            preds.entry(w).or_default().push(v);
        }
    }
    // super_exit -> each exit_node in forward = exit_node -> super_exit in rev
    for &e in exit_nodes {
        preds.entry(e).or_default().push(super_exit);
    }

    dominators(total, &preds, super_exit)
}

pub fn dominators(node_count: usize, preds: &HashMap<usize, Vec<usize>>, entry: usize) -> Vec<HashSet<usize>> {
    let all: HashSet<usize> = (0..node_count).collect();
    let mut dom: Vec<HashSet<usize>> = vec![all.clone(); node_count];
    if entry < node_count {
        dom[entry] = std::iter::once(entry).collect();
    }

    let mut changed = true;
    while changed {
        changed = false;
        for n in 0..node_count {
            if n == entry {
                continue;
            }
            let pred_list = preds.get(&n).cloned().unwrap_or_default();
            let mut new_dom = if pred_list.is_empty() {
                all.clone()
            } else {
                let mut iter = pred_list.iter().map(|p| dom[*p].clone());
                let first = iter.next().unwrap_or_default();
                iter.fold(first, |acc, s| acc.intersection(&s).cloned().collect())
            };
            new_dom.insert(n);
            if new_dom != dom[n] {
                dom[n] = new_dom;
                changed = true;
            }
        }
    }
    dom
}

