pub fn looping<T>(mut state: T, predicate: fn(&T) -> bool, step: fn(T) -> T) -> T {
    while predicate(&state) {
        state = step(state);
    }
    state
}

pub fn factorial(n: u64) -> u64 {
    if n <= 1 {
        1
    } else {
        n * factorial(n - 1)
    }
}

pub fn sequential<T>(mut state: T, steps: Vec<fn(T) -> T>) -> T {
    for step in steps {
        state = step(state);
    }
    state
}

