//! CPU Merkle tree over fixed-size blocks using SHA-256.
//!
//! Variables:
//!   L       = leaf count (must be power of 2)
//!   H       = 32 bytes  (SHA-256 digest size)
//!   tree[]  = flat array of 2*L nodes, each H bytes
//!             tree[L+i] = SHA256(block_i)        (leaves)
//!             tree[k/2] = SHA256(tree[k] || tree[k+1]) (parents)
//!
//! Equations:
//!   tree[L + i] = SHA256(data[i])
//!   tree[j]     = SHA256(tree[2j] || tree[2j+1])   for j in (L-1)..=1
//!   root        = tree[1]   (tree[0] unused, 1-indexed convention)
//!
//! Complexity: O(L) SHA-256 calls, O(log L) levels

use sha2::{Digest, Sha256};

pub const HASH_SIZE: usize = 32;

pub struct MerkleTree {
    pub nodes: Vec<[u8; HASH_SIZE]>, // length 2*L, 1-indexed (node[0] unused)
    pub leaf_count: usize,
}

impl MerkleTree {
    /// Build a Merkle tree from a slice of equal-sized blocks.
    /// leaf_count must be a power of 2.
    pub fn build(blocks: &[&[u8]]) -> Self {
        let l = blocks.len();
        assert!(l.is_power_of_two(), "leaf count must be power of 2");
        let mut nodes = vec![[0u8; HASH_SIZE]; 2 * l];

        // hash leaves
        for (i, block) in blocks.iter().enumerate() {
            let digest = Sha256::digest(block);
            nodes[l + i].copy_from_slice(&digest);
        }

        // build parents bottom-up
        for j in (1..l).rev() {
            let mut h = Sha256::new();
            h.update(nodes[2 * j]);
            h.update(nodes[2 * j + 1]);
            nodes[j].copy_from_slice(&h.finalize());
        }

        Self { nodes, leaf_count: l }
    }

    /// Root hash (tree[1]).
    pub fn root(&self) -> &[u8; HASH_SIZE] {
        &self.nodes[1]
    }

    /// Proof path for leaf i: sibling hashes from leaf to root.
    pub fn proof(&self, mut i: usize) -> Vec<[u8; HASH_SIZE]> {
        let mut path = Vec::new();
        i += self.leaf_count;
        while i > 1 {
            let sibling = if i % 2 == 0 { i + 1 } else { i - 1 };
            path.push(self.nodes[sibling]);
            i /= 2;
        }
        path
    }

    /// Verify a leaf against a proof path and expected root.
    pub fn verify(leaf_data: &[u8], mut index: usize, leaf_count: usize, proof: &[[u8; HASH_SIZE]], root: &[u8; HASH_SIZE]) -> bool {
        let mut current: [u8; HASH_SIZE] = Sha256::digest(leaf_data).into();
        index += leaf_count;
        for sibling in proof {
            let mut h = Sha256::new();
            if index % 2 == 0 {
                h.update(current);
                h.update(sibling);
            } else {
                h.update(sibling);
                h.update(current);
            }
            current = h.finalize().into();
            index /= 2;
        }
        &current == root
    }
}

//! FFI bridge to cryptography/merkle_tree.cu via unified libgpu.a.
//!
//! Variables:
//!   leaf_count : usize      — number of pages, must be power of 2
//!   pages      : &[u8]      — flat buffer of leaf_count * PAGE_SIZE bytes
//!   tree       : Vec<u8>    — output flat array, 2*L nodes each 32 bytes
//!                             tree[1*32..(1+1)*32] = root (1-indexed)
//!
//! Equations:
//!   tree[(L+i)*32 .. (L+i+1)*32] = SHA256(pages[i*4096 .. (i+1)*4096])
//!   tree[j*32 .. (j+1)*32]       = SHA256(tree[2j] || tree[2j+1])
//!   root = tree[32..64]   (node index 1)

pub const PAGE_SIZE: usize = 4096;
pub const HASH_SIZE: usize = 32;

#[cfg(feature = "cuda")]
unsafe extern "C" {
    fn gpu_merkle_build(tree: *mut u8, leaf_count: u64, pages: *const u8);
}

/// Build a GPU Merkle tree over `pages` (each PAGE_SIZE bytes).
/// Returns flat node array (2*L nodes, 32 bytes each, 1-indexed).
/// Root is at bytes [32..64].
#[cfg(feature = "cuda")]
pub fn merkle_build_gpu(pages: &[u8]) -> Vec<u8> {
    assert_eq!(pages.len() % PAGE_SIZE, 0, "pages not aligned to PAGE_SIZE");
    let l = pages.len() / PAGE_SIZE;
    assert!(l.is_power_of_two(), "leaf count must be power of 2");

    // 2*L nodes, each HASH_SIZE bytes, 1-indexed so node 0 is unused
    let mut tree = vec![0u8; 2 * l * HASH_SIZE];
    unsafe {
        gpu_merkle_build(tree.as_mut_ptr(), l as u64, pages.as_ptr());
    }
    tree
}

/// Extract root hash from a built tree (node index 1).
pub fn root(tree: &[u8]) -> &[u8] {
    &tree[HASH_SIZE..HASH_SIZE * 2]
}

