//! Bump-pointer arena allocator.
//!
//! Variables:
//!   buf : Vec<u8>  — backing slab, allocated once at construction
//!   len : usize    — current bump offset (next free byte)
//!   cap : usize    — total capacity = buf.len()
//!
//! Equations:
//!   alloc(n, align):
//!     pad  = (align - len % align) % align
//!     start= len + pad
//!     len' = start + n  ,  len' <= cap  (else panic)
//!     returns &mut buf[start .. start+n]
//!
//!   reset():
//!     len = 0          O(1) — no individual frees needed
//!
//!   utilisation = len / cap

pub struct Arena {
    buf: Vec<u8>,
    len: usize,
}

impl Arena {
    /// Allocate a new arena with `capacity` bytes.
    pub fn new(capacity: usize) -> Self {
        Self { buf: vec![0u8; capacity], len: 0 }
    }

    /// Bump-allocate `count` values of type T (alignment respected).
    /// Returns a mutable slice into the arena's backing buffer.
    /// Panics if remaining capacity is insufficient.
    pub fn alloc_slice<T: Copy>(&mut self, count: usize) -> &mut [T] {
        let align = std::mem::align_of::<T>();
        let size = std::mem::size_of::<T>();

        let pad = (align - self.len % align) % align;
        let start = self.len + pad;
        let end = start + size * count;

        assert!(end <= self.buf.len(), "arena out of capacity");

        self.len = end;

        let ptr = unsafe { self.buf.as_mut_ptr().add(start) as *mut T };

        // SAFETY:
        // - `start` is aligned for T
        // - region [start, end) is within buf
        // - &mut self guarantees unique access
        unsafe { std::slice::from_raw_parts_mut(ptr, count) }
    }

    /// Allocate a single value of type T, initialised to `val`.
    pub fn alloc<T: Copy>(&mut self, val: T) -> &mut T {
        let slice = self.alloc_slice::<T>(1);
        slice[0] = val;
        &mut slice[0]
    }

    /// Reset bump offset to zero — O(1) free of all allocations.
    pub fn reset(&mut self) {
        self.len = 0;
    }

    /// Bytes used / bytes capacity.
    pub fn utilisation(&self) -> (usize, usize) {
        (self.len, self.buf.len())
    }
}

//! Fixed-size array with bounds-checked access.
//!
//! Variables:
//!   data : Vec<T>  — backing storage, length fixed at construction
//!   N    : usize   — length, immutable after new()
//!
//! Equations:
//!   get(i):  i < N  => Some(&data[i]),  else None    O(1)
//!   set(i,x):i < N  => data[i] = x,     else panic   O(1)
//!   rotate_left(k):  data[i] = data[(i+k) mod N]     O(N)

pub struct Array<T> {
    data: Vec<T>,
}

impl<T: Clone + Default> Array<T> {
    pub fn new(len: usize) -> Self {
        Self { data: vec![T::default(); len] }
    }

    pub fn from_vec(v: Vec<T>) -> Self {
        Self { data: v }
    }

    pub fn get(&self, i: usize) -> Option<&T> {
        self.data.get(i)
    }
    pub fn get_mut(&mut self, i: usize) -> Option<&mut T> {
        self.data.get_mut(i)
    }
    pub fn set(&mut self, i: usize, val: T) {
        self.data[i] = val;
    }
    pub fn len(&self) -> usize {
        self.data.len()
    }
    pub fn as_slice(&self) -> &[T] {
        &self.data
    }

    /// Rotate elements left by k positions: data[i] <- data[(i+k) % N]
    pub fn rotate_left(&mut self, k: usize) {
        let n = self.data.len();
        self.data.rotate_left(k % n);
    }

    /// Rotate elements right by k positions.
    pub fn rotate_right(&mut self, k: usize) {
        let n = self.data.len();
        self.data.rotate_right(k % n);
    }
}

//! Open-addressing hash table with linear probing.
//!
//! Variables:
//!   buckets  : Vec<Option<(K,V)>>  — slot array, length C (capacity)
//!   occupied : usize               — number of live entries
//!   C        : usize               — capacity, always power of 2
//!
//! Equations:
//!   h(k)         = k.hash() mod C                      (home slot)
//!   probe(h, i)  = (h + i) mod C                       (linear probe step i)
//!   load_factor  = occupied / C
//!   resize when load_factor > 0.7: C' = 2*C, rehash all entries
//!
//!   insert(k,v): probe from h(k) until empty slot,  O(1) amortised
//!   get(k):      probe from h(k) until k found or empty, O(1) amortised
//!   remove(k):   tombstone slot (set to None), O(1) amortised

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

pub struct HashTable<K: Hash + Eq + Clone, V: Clone> {
    buckets: Vec<Option<(K, V)>>,
    occupied: usize,
}

impl<K: Hash + Eq + Clone, V: Clone> HashTable<K, V> {
    pub fn new() -> Self {
        Self { buckets: vec![None; 16], occupied: 0 }
    }

    fn hash_index(&self, key: &K) -> usize {
        let mut h = DefaultHasher::new();
        key.hash(&mut h);
        (h.finish() as usize) & (self.buckets.len() - 1)
    }

    pub fn insert(&mut self, key: K, val: V) {
        if self.occupied * 10 >= self.buckets.len() * 7 {
            self.resize();
        }
        let mut i = self.hash_index(&key);
        loop {
            match &self.buckets[i] {
                None => {
                    self.buckets[i] = Some((key, val));
                    self.occupied += 1;
                    return;
                }
                Some((k, _)) if *k == key => {
                    self.buckets[i] = Some((key, val));
                    return;
                }
                _ => {
                    i = (i + 1) & (self.buckets.len() - 1);
                }
            }
        }
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        let mut i = self.hash_index(key);
        loop {
            match &self.buckets[i] {
                None => return None,
                Some((k, v)) if k == key => return Some(v),
                _ => {
                    i = (i + 1) & (self.buckets.len() - 1);
                }
            }
        }
    }

    pub fn remove(&mut self, key: &K) -> bool {
        let mut i = self.hash_index(key);
        loop {
            match &self.buckets[i] {
                None => return false,
                Some((k, _)) if k == key => {
                    self.buckets[i] = None;
                    self.occupied -= 1;
                    return true;
                }
                _ => {
                    i = (i + 1) & (self.buckets.len() - 1);
                }
            }
        }
    }

    pub fn len(&self) -> usize {
        self.occupied
    }
    pub fn is_empty(&self) -> bool {
        self.occupied == 0
    }

    fn resize(&mut self) {
        let new_cap = self.buckets.len() * 2;
        let mut new_buckets: Vec<Option<(K, V)>> = vec![None; new_cap];
        for slot in self.buckets.drain(..) {
            if let Some((k, v)) = slot {
                let mut h = DefaultHasher::new();
                k.hash(&mut h);
                let mut i = (h.finish() as usize) & (new_cap - 1);
                while new_buckets[i].is_some() {
                    i = (i + 1) & (new_cap - 1);
                }
                new_buckets[i] = Some((k, v));
            }
        }
        self.buckets = new_buckets;
    }
}

//! Binary min-heap.
//!
//! Variables:
//!   data : Vec<T>  — heap array, 0-indexed
//!   N    : usize   — current size
//!
//! Equations:
//!   parent(i)     = (i - 1) / 2
//!   left_child(i) = 2*i + 1
//!   right_child(i)= 2*i + 2
//!
//!   Heap invariant: data[parent(i)] <= data[i]  for all i > 0
//!
//!   push(x):   data[N] = x,  sift_up(N),    N' = N+1   O(log N)
//!   pop_min(): swap(0, N-1), N' = N-1, sift_down(0)     O(log N)

pub struct MinHeap<T: Ord> {
    data: Vec<T>,
}

impl<T: Ord> MinHeap<T> {
    pub fn new() -> Self {
        Self { data: Vec::new() }
    }

    pub fn push(&mut self, val: T) {
        self.data.push(val);
        self.sift_up(self.data.len() - 1);
    }

    pub fn pop_min(&mut self) -> Option<T> {
        if self.data.is_empty() {
            return None;
        }
        let n = self.data.len() - 1;
        self.data.swap(0, n);
        let min = self.data.pop();
        if !self.data.is_empty() {
            self.sift_down(0);
        }
        min
    }

    pub fn peek_min(&self) -> Option<&T> {
        self.data.first()
    }
    pub fn len(&self) -> usize {
        self.data.len()
    }
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    fn sift_up(&mut self, mut i: usize) {
        while i > 0 {
            let p = (i - 1) / 2;
            if self.data[p] <= self.data[i] {
                break;
            }
            self.data.swap(p, i);
            i = p;
        }
    }

    fn sift_down(&mut self, mut i: usize) {
        let n = self.data.len();
        loop {
            let mut smallest = i;
            let l = 2 * i + 1;
            let r = 2 * i + 2;
            if l < n && self.data[l] < self.data[smallest] {
                smallest = l;
            }
            if r < n && self.data[r] < self.data[smallest] {
                smallest = r;
            }
            if smallest == i {
                break;
            }
            self.data.swap(i, smallest);
            i = smallest;
        }
    }
}

//! Singly-linked list with owned nodes.
//!
//! Variables:
//!   head : Option<Box<Node<T>>>  — pointer to first node, None if empty
//!   N    : usize                 — number of nodes
//!
//! Equations:
//!   push_front(x): new_node.next = head,  head = new_node,  N' = N+1  O(1)
//!   pop_front():   head = head.next,  N' = N-1                         O(1)
//!   push_back(x):  walk to tail, tail.next = new_node                  O(N)

struct Node<T> {
    val: T,
    next: Option<Box<Node<T>>>,
}

pub struct LinkedList<T> {
    head: Option<Box<Node<T>>>,
    len: usize,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        Self { head: None, len: 0 }
    }

    pub fn push_front(&mut self, val: T) {
        let node = Box::new(Node { val, next: self.head.take() });
        self.head = Some(node);
        self.len += 1;
    }

    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|node| {
            self.head = node.next;
            self.len -= 1;
            node.val
        })
    }

    pub fn push_back(&mut self, val: T) {
        let new_node = Box::new(Node { val, next: None });
        let mut cur = &mut self.head;
        while let Some(node) = cur {
            cur = &mut node.next;
        }
        *cur = Some(new_node);
        self.len += 1;
    }

    pub fn peek_front(&self) -> Option<&T> {
        self.head.as_ref().map(|n| &n.val)
    }

    pub fn len(&self) -> usize {
        self.len
    }
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

//! Queue — FIFO ring buffer of fixed capacity.
//!
//! Variables:
//!   buf  : Vec<Option<T>>  — circular backing array, length C
//!   head : usize           — index of next dequeue
//!   tail : usize           — index of next enqueue
//!   len  : usize           — current occupancy
//!
//! Equations:
//!   enqueue(x): buf[tail] = x,  tail = (tail+1) mod C,  len += 1
//!   dequeue():  x = buf[head],  head = (head+1) mod C,  len -= 1
//!   full  iff len == C
//!   empty iff len == 0

pub struct Queue<T> {
    buf: Vec<Option<T>>,
    head: usize,
    tail: usize,
    len: usize,
}

impl<T> Queue<T> {
    pub fn new(capacity: usize) -> Self {
        let mut buf = Vec::with_capacity(capacity);
        for _ in 0..capacity {
            buf.push(None);
        }
        Self { buf, head: 0, tail: 0, len: 0 }
    }

    pub fn enqueue(&mut self, val: T) -> bool {
        if self.len == self.buf.len() {
            return false;
        }
        self.buf[self.tail] = Some(val);
        self.tail = (self.tail + 1) % self.buf.len();
        self.len += 1;
        true
    }

    pub fn dequeue(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let val = self.buf[self.head].take();
        self.head = (self.head + 1) % self.buf.len();
        self.len -= 1;
        val
    }

    pub fn peek(&self) -> Option<&T> {
        self.buf[self.head].as_ref()
    }
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
    pub fn is_full(&self) -> bool {
        self.len == self.buf.len()
    }
    pub fn len(&self) -> usize {
        self.len
    }
}

//! Stack — LIFO structure backed by Vec.
//!
//! Variables:
//!   data : Vec<T>  — backing storage
//!   N    : usize   — current number of elements = data.len()
//!
//! Equations:
//!   push(x): data[N] = x,  N' = N + 1       O(1) amortised
//!   pop():   N' = N - 1,   returns data[N-1] O(1)
//!   peek():  returns &data[N-1]              O(1)

pub struct Stack<T> {
    data: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Self { data: Vec::new() }
    }
    pub fn push(&mut self, val: T) {
        self.data.push(val);
    }
    pub fn pop(&mut self) -> Option<T> {
        self.data.pop()
    }
    pub fn peek(&self) -> Option<&T> {
        self.data.last()
    }
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }
    pub fn len(&self) -> usize {
        self.data.len()
    }
}

#[derive(Debug, Clone)]
pub struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<u8>,
    components: usize,
}

impl UnionFind {
    pub fn new(size: usize) -> Self {
        let parent = (0..size).collect::<Vec<_>>();
        let rank = vec![0u8; size];
        Self { parent, rank, components: size }
    }

    pub fn len(&self) -> usize {
        self.parent.len()
    }

    pub fn is_empty(&self) -> bool {
        self.parent.is_empty()
    }

    pub fn components(&self) -> usize {
        self.components
    }

    pub fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }

        let mut cur = x;
        while self.parent[cur] != cur {
            let next = self.parent[cur];
            self.parent[cur] = root;
            cur = next;
        }

        root
    }

    pub fn union(&mut self, a: usize, b: usize) -> bool {
        let mut ra = self.find(a);
        let mut rb = self.find(b);
        if ra == rb {
            return false;
        }

        if self.rank[ra] < self.rank[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }
        self.parent[rb] = ra;
        if self.rank[ra] == self.rank[rb] {
            self.rank[ra] = self.rank[ra].saturating_add(1);
        }
        self.components = self.components.saturating_sub(1);
        true
    }

    pub fn labels(&mut self) -> Vec<usize> {
        (0..self.parent.len()).map(|i| self.find(i)).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::UnionFind;

    #[test]
    fn union_find_merges_components() {
        let mut uf = UnionFind::new(6);
        assert_eq!(uf.components(), 6);

        assert!(uf.union(0, 1));
        assert!(uf.union(1, 2));
        assert!(uf.union(3, 4));
        assert_eq!(uf.components(), 3);

        let r0 = uf.find(0);
        let r2 = uf.find(2);
        let r3 = uf.find(3);
        let r4 = uf.find(4);
        assert_eq!(r0, r2);
        assert_eq!(r3, r4);
        assert_ne!(r0, r3);
    }

    #[test]
    fn redundant_union_is_noop() {
        let mut uf = UnionFind::new(3);
        assert!(uf.union(0, 1));
        assert!(!uf.union(0, 1));
        assert_eq!(uf.components(), 2);
    }
}

use std::collections::HashMap;

pub fn fib_memo(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    if n <= 1 {
        return n;
    }
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let val = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
    memo.insert(n, val);
    val
}

pub fn fib_tab(n: usize) -> u64 {
    if n <= 1 {
        return n as u64;
    }
    let mut dp = vec![0u64; n + 1];
    dp[1] = 1;
    for i in 2..=n {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    dp[n]
}

