use std::cmp::Reverse;
use std::collections::BinaryHeap;

/// A* search on a weighted directed graph.
///
/// `graph[u]` = Vec of (v, weight).
/// `heuristic(v)` must be admissible for optimality.
///
/// Returns (cost, path) from start to goal if reachable.
pub fn a_star(graph: &[Vec<(usize, u64)>], start: usize, goal: usize, heuristic: impl Fn(usize) -> u64) -> Option<(u64, Vec<usize>)> {
    if start >= graph.len() || goal >= graph.len() {
        return None;
    }

    let n = graph.len();
    let mut g_score = vec![u64::MAX; n];
    let mut came_from: Vec<Option<usize>> = vec![None; n];
    let mut open = BinaryHeap::new();

    g_score[start] = 0;
    open.push((Reverse(heuristic(start)), start));

    while let Some((Reverse(_f), u)) = open.pop() {
        if u == goal {
            return Some((g_score[u], reconstruct_path(goal, &came_from)));
        }
        let base = g_score[u];
        if base == u64::MAX {
            continue;
        }
        for &(v, w) in &graph[u] {
            let cand = base.saturating_add(w);
            if cand < g_score[v] {
                g_score[v] = cand;
                came_from[v] = Some(u);
                let f = cand.saturating_add(heuristic(v));
                open.push((Reverse(f), v));
            }
        }
    }
    None
}

fn reconstruct_path(goal: usize, came_from: &[Option<usize>]) -> Vec<usize> {
    let mut path = Vec::new();
    let mut cur = Some(goal);
    while let Some(v) = cur {
        path.push(v);
        cur = came_from[v];
    }
    path.reverse();
    path
}

//! Adjacency list graph representation.
//!
//! Variables:
//!   V       = number of vertices
//!   E       = number of directed edges
//!   adj[u]  = Vec<usize> of out-neighbours of vertex u
//!
//! Equations:
//!   add_edge(u, v):  adj[u].push(v),  E += 1
//!   out_degree(u)  = |adj[u]|
//!   in_degree(v)   = |{ u | v in adj[u] }|   (O(V+E) to compute)
//!   add_undirected(u,v): add_edge(u,v) + add_edge(v,u),  E += 2
//!
//! Conversion to CSR (see graph::csr):
//!   row_ptr[v] = sum_{u=0}^{v-1} out_degree(u)
//!   col_idx    = adj[0] ++ adj[1] ++ ... ++ adj[V-1]

use super::csr::Csr;

pub struct AdjList {
    pub adj: Vec<Vec<usize>>,
}

impl AdjList {
    /// Create an empty graph with `v` vertices and no edges.
    pub fn new(v: usize) -> Self {
        Self { adj: vec![Vec::new(); v] }
    }

    pub fn vertex_count(&self) -> usize {
        self.adj.len()
    }

    pub fn edge_count(&self) -> usize {
        self.adj.iter().map(|n| n.len()).sum()
    }

    /// Add a directed edge u -> v.
    pub fn add_edge(&mut self, u: usize, v: usize) {
        self.adj[u].push(v);
    }

    /// Add undirected edge (both directions).
    pub fn add_undirected(&mut self, u: usize, v: usize) {
        self.adj[u].push(v);
        self.adj[v].push(u);
    }

    pub fn neighbours(&self, u: usize) -> &[usize] {
        &self.adj[u]
    }

    /// Convert to CSR — O(V+E).
    pub fn to_csr(&self) -> Csr {
        Csr::from_adj(&self.adj)
    }

    /// Borrow inner slice for algorithms expecting &[Vec<usize>].
    pub fn as_slice(&self) -> &[Vec<usize>] {
        &self.adj
    }
}

//! Bellman-Ford single-source shortest paths.
//!
//! Variables:
//!   V       = number of vertices
//!   E       = edge list as (u, v, weight)
//!   dist[v] = shortest known distance from source to v
//!   INF     = u64::MAX / 2  (sentinel for unreachable)
//!
//! Equations:
//!   Initialise: dist[source] = 0,  dist[v] = INF  for v != source
//!
//!   Relax (repeated V-1 times):
//!     for each (u, v, w) in E:
//!       dist[v] = min(dist[v], dist[u] + w)
//!
//!   Negative cycle detection (pass V):
//!     if any edge still relaxes => negative cycle exists
//!
//!   Complexity: O(V * E)

pub const INF: u64 = u64::MAX / 2;

/// Returns None if a negative-weight cycle is reachable from source.
/// Otherwise returns dist[] where dist[v] = shortest path length source->v.
pub fn bellman_ford(v: usize, edges: &[(usize, usize, u64)], source: usize) -> Option<Vec<u64>> {
    let mut dist = vec![INF; v];
    dist[source] = 0;

    if v == 0 {
        return Some(dist);
    }

    for _ in 0..v - 1 {
        let mut updated = false;

        for &(u, w, weight) in edges {
            if dist[u] != INF {
                let candidate = dist[u].saturating_add(weight);
                if candidate < dist[w] {
                    dist[w] = candidate;
                    updated = true;
                }
            }
        }

        if !updated {
            break;
        }
    }

    // V-th pass: negative cycle check
    for &(u, w, weight) in edges {
        if dist[u] != INF {
            let candidate = dist[u].saturating_add(weight);
            if candidate < dist[w] {
                return None;
            }
        }
    }

    Some(dist)
}

//! FFI bridge to graph/bellman_ford.cu via unified libgpu.a.
//!
//! Variables:
//!   edges_flat : flat (u, v, w) triples as u64, length E*3
//!   V, E       : vertex and edge counts
//!   source     : start vertex
//!
//! Equation:
//!   dist[v] = shortest path source->v, or INF if unreachable
//!   Returns Err if a negative-weight cycle is reachable from source

use super::bellman_ford::INF;

#[cfg(feature = "cuda")]
unsafe extern "C" {
    fn gpu_bellman_ford(edges_flat: *const u64, v: i32, e: i32, source: i32, dist_out: *mut u64) -> i32;
}

/// Run GPU Bellman-Ford. Returns Ok(dist) or Err("negative cycle").
#[cfg(feature = "cuda")]
pub fn bellman_ford_gpu(v: usize, edges: &[(usize, usize, u64)], source: usize) -> Result<Vec<u64>, &'static str> {
    // flatten edges to (u, v, w) u64 triples
    let flat: Vec<u64> = edges.iter().flat_map(|&(u, v, weight)| [u as u64, v as u64, weight]).collect();

    let mut dist = vec![INF; v];

    let neg_cycle = unsafe { gpu_bellman_ford(flat.as_ptr(), v as i32, edges.len() as i32, source as i32, dist.as_mut_ptr()) };

    if neg_cycle != 0 {
        Err("negative cycle detected")
    } else {
        Ok(dist)
    }
}

//! Compressed Sparse Row (CSR) graph representation.
//!
//! Variables:
//!   V        = number of vertices
//!   E        = number of edges
//!   row_ptr  = prefix-sum of out-degrees, length V+1
//!   col_idx  = concatenated neighbour lists,  length E
//!
//! Equations:
//!   row_ptr[0] = 0
//!   row_ptr[v+1] = row_ptr[v] + out_degree(v)
//!   neighbours(v) = col_idx[ row_ptr[v] .. row_ptr[v+1] ]
//!
//! Conversion from adjacency list:
//!   row_ptr[v] = sum_{u=0}^{v-1} |adj[u]|
//!   col_idx    = adj[0] ++ adj[1] ++ ... ++ adj[V-1]   (concatenation)

pub struct Csr {
    pub row_ptr: Vec<i32>, // length V+1
    pub col_idx: Vec<i32>, // length E
}

impl Csr {
    /// Build CSR from an adjacency list (each inner vec is a neighbour list).
    pub fn from_adj(adj: &[Vec<usize>]) -> Self {
        let mut row_ptr = Vec::with_capacity(adj.len() + 1);
        let mut col_idx = Vec::new();

        row_ptr.push(0i32);

        for neighbours in adj {
            for &v in neighbours {
                col_idx.push(v as i32);
            }
            row_ptr.push(col_idx.len() as i32);
        }

        Self { row_ptr, col_idx }
    }

    pub fn vertex_count(&self) -> usize {
        self.row_ptr.len() - 1
    }

    pub fn edge_count(&self) -> usize {
        self.col_idx.len()
    }

    /// Iterator over neighbours of vertex v.
    pub fn neighbours(&self, v: usize) -> &[i32] {
        let start = self.row_ptr[v] as usize;
        let end = self.row_ptr[v + 1] as usize;
        &self.col_idx[start..end]
    }

    /// Build CSR from edge list (u -> v) with a known vertex count.
    pub fn from_edges(vertex_count: usize, edges: &[(usize, usize)]) -> Self {
        let mut adj = vec![Vec::new(); vertex_count];
        for &(u, v) in edges {
            if u < vertex_count && v < vertex_count {
                adj[u].push(v);
            }
        }
        Self::from_adj(&adj)
    }

    /// Convert CSR back to adjacency list.
    pub fn to_adj(&self) -> Vec<Vec<usize>> {
        let mut adj = vec![Vec::new(); self.vertex_count()];
        for u in 0..self.vertex_count() {
            for &v in self.neighbours(u) {
                adj[u].push(v as usize);
            }
        }
        adj
    }
}

//! Unified-memory CSR built on GPU via cudaMallocManaged.
//!
//! Variables:
//!   row_ptr : *mut i32  — unified pointer, length V+1, valid CPU+GPU
//!   col_idx : *mut i32  — unified pointer, length E,   valid CPU+GPU
//!   V, E    : usize     — vertex and edge counts
//!
//! Equations:
//!   row_ptr[v+1] - row_ptr[v] = out_degree(v)
//!   col_idx[row_ptr[v]..row_ptr[v+1]] = neighbours(v)
//!
//! Unlike Csr (host Vec), these pointers can be passed directly to any
//! CUDA kernel without cudaMemcpy. The driver page-migrates on first access.
//! cudaMemPrefetchAsync is called after build to warm CPU-side reads.

use super::adj_list::AdjList;

#[cfg(feature = "cuda")]
unsafe extern "C" {
    fn gpu_csr_build(adj_flat: *const i32, v: i32, e: i32, row_ptr_out: *mut *mut i32, col_idx_out: *mut *mut i32);
    fn gpu_csr_free(row_ptr: *mut i32, col_idx: *mut i32);
}

#[cfg(feature = "cuda")]
pub struct CsrUnified {
    pub row_ptr: *mut i32, // unified, length V+1
    pub col_idx: *mut i32, // unified, length E
    pub v: usize,
    pub e: usize,
}

#[cfg(feature = "cuda")]
impl CsrUnified {
    /// Build unified CSR from an AdjList on the GPU.
    pub fn from_adj(adj: &AdjList) -> Self {
        // Flatten adjacency list to (u,v) pairs
        let mut flat: Vec<i32> = Vec::with_capacity(adj.edge_count() * 2);
        for (u, neighbours) in adj.adj.iter().enumerate() {
            for &v in neighbours {
                flat.push(u as i32);
                flat.push(v as i32);
            }
        }
        let v = adj.vertex_count();
        let e = adj.edge_count();
        let mut row_ptr: *mut i32 = std::ptr::null_mut();
        let mut col_idx: *mut i32 = std::ptr::null_mut();
        unsafe {
            gpu_csr_build(flat.as_ptr(), v as i32, e as i32, &mut row_ptr, &mut col_idx);
        }
        Self { row_ptr, col_idx, v, e }
    }

    pub fn vertex_count(&self) -> usize {
        self.v
    }
    pub fn edge_count(&self) -> usize {
        self.e
    }

    /// Safe slice view of row_ptr (host-accessible via unified memory).
    pub fn row_ptr_slice(&self) -> &[i32] {
        unsafe { std::slice::from_raw_parts(self.row_ptr, self.v + 1) }
    }

    /// Safe slice view of col_idx.
    pub fn col_idx_slice(&self) -> &[i32] {
        unsafe { std::slice::from_raw_parts(self.col_idx, self.e) }
    }
}

#[cfg(feature = "cuda")]
impl Drop for CsrUnified {
    fn drop(&mut self) {
        unsafe {
            gpu_csr_free(self.row_ptr, self.col_idx);
        }
    }
}

