    fn gpu_reachability(row_ptr: *const i32, col_idx: *const i32, v: i32, e: i32, roots: *const i32, root_count: i32, visited_out: *mut i32);
    fn gpu_reachability_batched(row_ptr: *const i32, col_idx: *const i32, v: i32, e: i32, roots: *const i32, r: i32, out: *mut i32);
    fn gpu_reachability_tc(row_ptr: *const i32, col_idx: *const i32, v: i32, e: i32, w: i32, max_iters: i32, out: *mut u64);
}

/// GPU reachability from a set of roots. Returns visited mask.
#[cfg(feature = "cuda")]
pub fn reachability_gpu(csr: &Csr, roots: &[usize]) -> Vec<bool> {
    let mut visited = vec![0i32; csr.vertex_count()];
    let roots_i32: Vec<i32> = roots.iter().map(|&r| r as i32).collect();
    unsafe {
        gpu_reachability(csr.row_ptr.as_ptr(), csr.col_idx.as_ptr(), csr.vertex_count() as i32, csr.edge_count() as i32, roots_i32.as_ptr(), roots_i32.len() as i32, visited.as_mut_ptr());
    }
    visited.into_iter().map(|v| v != 0).collect()
}

/// GPU reachability from roots bounded by max_depth (inclusive).
#[cfg(feature = "cuda")]
pub fn reachability_bounded(csr: &Csr, roots: &[usize], max_depth: usize) -> Vec<bool> {
    if csr.vertex_count() == 0 {
        return Vec::new();
    }
    if max_depth == 0 {
        return vec![false; csr.vertex_count()];
    }
    let mut visited = vec![false; csr.vertex_count()];
    for &root in roots {
        let levels = gpu::bfs_gpu(csr, root);
        for (idx, lvl) in levels.into_iter().enumerate() {
            if lvl >= 0 && (lvl as usize) <= max_depth {
                visited[idx] = true;
            }
        }
    }
    visited
}

/// GPU batched reachability — one BFS per root in parallel.
/// Returns flat R×V row-major matrix: out[r*V + v] = true if v reachable from roots[r].
#[cfg(feature = "cuda")]
pub fn reachability_batched_gpu(csr: &Csr, roots: &[usize]) -> Vec<Vec<bool>> {
    let r = roots.len();
    let v = csr.vertex_count();
    if r == 0 || v == 0 {
        return vec![vec![false; v]; r];
    }
    let out = reachability_batched_flat_gpu(csr, roots);
    out.chunks(v).map(|row| row.iter().map(|&x| x != 0).collect()).collect()
}

/// GPU batched reachability — returns flat R×V row-major i32 matrix.
#[cfg(feature = "cuda")]
pub fn reachability_batched_flat_gpu(csr: &Csr, roots: &[usize]) -> Vec<i32> {
    let r = roots.len();
    let v = csr.vertex_count();
    if r == 0 || v == 0 {
        return Vec::new();
    }
    let roots_i32: Vec<i32> = roots.iter().map(|&x| x as i32).collect();
    let mut out = vec![0i32; r * v];
    unsafe {
        gpu_reachability_batched(
            csr.row_ptr.as_ptr(),
            csr.col_idx.as_ptr(),
            v as i32,
            csr.edge_count() as i32,
            roots_i32.as_ptr(),
            r as i32,
            out.as_mut_ptr(),
        );
    }
    out
}

/// GPU transitive closure using bitset propagation.
/// Returns flat V×W row-major bitset matrix where W = ceil(V/64).
#[cfg(feature = "cuda")]
pub fn reachability_tc_gpu(csr: &Csr, max_iters: usize) -> Vec<u64> {
    let v = csr.vertex_count();
    if v == 0 {
        return Vec::new();
    }
    let w = (v + 63) / 64;
    let mut out = vec![0u64; v * w];
    unsafe {
        gpu_reachability_tc(
            csr.row_ptr.as_ptr(),
            csr.col_idx.as_ptr(),
            v as i32,
            csr.edge_count() as i32,
            w as i32,
            max_iters as i32,
            out.as_mut_ptr(),
        );
    }
    out
}

//! Region / lifetime constraint analysis.
//!
//! Variables:
//!   adj     : &[Vec<usize>]       — G_region adjacency list
//!                                   edge u->v means lifetime u outlives v ('u: 'v)
//!   sccs    : Vec<Vec<usize>>     — Kosaraju SCCs of adj
//!
//! Equations:
//!   outlives_cycles(adj) = { scc | scc ∈ kosaraju_scc(adj), |scc| > 1 }
//!
//!   A cycle in G_region means 'a: 'b ∧ 'b: 'a — a contradictory constraint.
//!   outlives_cycles returns all such conflicting groups.
//!   An empty result means the region graph is a valid DAG.

use super::scc::kosaraju_scc;

/// Returns all groups of mutually-conflicting lifetime nodes (SCC size > 1).
///
/// Equation:
///   outlives_cycles(adj) = [ scc | scc ∈ kosaraju_scc(adj), |scc| > 1 ]
pub fn outlives_cycles(adj: &[Vec<usize>]) -> Vec<Vec<usize>> {
    kosaraju_scc(adj).into_iter().filter(|scc| scc.len() > 1).collect()
}

//! Strongly connected components (Kosaraju).
//!
//! Returns SCCs as vectors of node indices.

pub fn kosaraju_scc(adj: &[Vec<usize>]) -> Vec<Vec<usize>> {
    let n = adj.len();
    if n == 0 {
        return Vec::new();
    }

    // First pass: compute finish order on original graph.
    let mut visited = vec![false; n];
    let mut order: Vec<usize> = Vec::with_capacity(n);

    fn dfs_finish(v: usize, adj: &[Vec<usize>], visited: &mut [bool], order: &mut Vec<usize>) {
        visited[v] = true;
        for &u in &adj[v] {
            if !visited[u] {
                dfs_finish(u, adj, visited, order);
            }
        }
        order.push(v);
    }

    for v in 0..n {
        if !visited[v] {
            dfs_finish(v, adj, &mut visited, &mut order);
        }
    }

    // Reverse graph.
    let mut rev: Vec<Vec<usize>> = vec![Vec::new(); n];
    for (v, edges) in adj.iter().enumerate() {
        for &u in edges {
            rev[u].push(v);
        }
    }

    // Second pass: DFS on reversed graph in decreasing finish order.
    visited.fill(false);
    let mut comps: Vec<Vec<usize>> = Vec::new();

    fn dfs_collect(v: usize, adj: &[Vec<usize>], visited: &mut [bool], comp: &mut Vec<usize>) {
        visited[v] = true;
        comp.push(v);
        for &u in &adj[v] {
            if !visited[u] {
                dfs_collect(u, adj, visited, comp);
            }
        }
    }

    for &v in order.iter().rev() {
        if !visited[v] {
            let mut comp = Vec::new();
            dfs_collect(v, &rev, &mut visited, &mut comp);
            comps.push(comp);
        }
    }

    comps
}

//! GPU-accelerated SCC via forward/reverse reachability.
//! Uses GPU reachability kernel for each node (O(V*(V+E))).

use super::csr::Csr;
use super::reachability::reachability_tc_gpu;

#[cfg(feature = "cuda")]
pub fn scc_gpu(csr: &Csr) -> Vec<Vec<usize>> {
    let v = csr.vertex_count();
    if v == 0 {
        return Vec::new();
    }
    let mut rev_adj: Vec<Vec<usize>> = vec![Vec::new(); v];
    for u in 0..v {
        let start = csr.row_ptr[u] as usize;
        let end = csr.row_ptr[u + 1] as usize;
        for &to in &csr.col_idx[start..end] {
            rev_adj[to as usize].push(u);
        }
    }
    let rev = Csr::from_adj(&rev_adj);
    let w = (v + 63) / 64;
    let to = reachability_tc_gpu(csr, v);
    let from = reachability_tc_gpu(&rev, v);
    let mut assigned_words = vec![0u64; w];
    let mut sccs = Vec::new();
    for i in 0..v {
        let word = i >> 6;
        let bit = i & 63;
        if (assigned_words[word] >> bit) & 1 != 0 {
            continue;
        }
        let base = i * w;
        let mut comp = Vec::new();
        for wi in 0..w {
            let mut bits = to[base + wi] & from[base + wi] & !assigned_words[wi];
            while bits != 0 {
                let tz = bits.trailing_zeros() as usize;
                let j = wi * 64 + tz;
                if j < v {
                    assigned_words[wi] |= 1u64 << tz;
                    comp.push(j);
                }
                bits &= bits - 1;
            }
        }
        if !comp.is_empty() {
            sccs.push(comp);
        }
    }
    sccs
}

//! GPU ready-mask kernel for scheduler graphs.

#[cfg(feature = "cuda")]
unsafe extern "C" {
    fn gpu_ready_mask(status: *const u8, deps_offset: *const i32, deps_flat: *const i32, v: i32, ready_out: *mut u8, ready_count_out: *mut i32, completed_count_out: *mut i32);
    fn gpu_pack_ready_priority(ready_mask: *const u8, priority: *const u16, v: i32, out_keys: *mut i64);
}

/// Run GPU ready-mask kernel. Returns (ready_mask, ready_count, completed_count).
#[cfg(feature = "cuda")]
pub fn ready_mask_gpu(status: &[u8], deps_offset: &[i32], deps_flat: &[i32]) -> (Vec<u8>, i32, i32) {
    let v = status.len() as i32;
    let mut ready = vec![0u8; status.len()];
    let mut ready_count = 0i32;
    let mut completed_count = 0i32;
    unsafe {
        gpu_ready_mask(status.as_ptr(), deps_offset.as_ptr(), deps_flat.as_ptr(), v, ready.as_mut_ptr(), &mut ready_count, &mut completed_count);
    }
    (ready, ready_count, completed_count)
}

/// Pack (priority, index) into keys for GPU sorting. key = (priority << 32) | index.
#[cfg(feature = "cuda")]
pub fn pack_ready_priority(ready_mask: &[u8], priority: &[u16]) -> Vec<i64> {
    let v = ready_mask.len() as i32;
    let mut keys = vec![-1i64; ready_mask.len()];
    unsafe {
        gpu_pack_ready_priority(ready_mask.as_ptr(), priority.as_ptr(), v, keys.as_mut_ptr());
    }
    keys
}

/// Deadlock check using GPU ready-mask counters.
#[cfg(feature = "cuda")]
pub fn deadlock_gpu(status: &[u8], deps_offset: &[i32], deps_flat: &[i32]) -> bool {
    let (_ready, ready_count, completed_count) = ready_mask_gpu(status, deps_offset, deps_flat);
    let total = status.len() as i32;
    ready_count == 0 && completed_count < total
}

use std::collections::VecDeque;

/// Topological scheduling: returns layers of nodes that can execute in parallel.
///
/// `adj[u]` is the list of outgoing edges from u to v.
pub fn topological_layers(adj: &[Vec<usize>]) -> Vec<Vec<usize>> {
    let mut indegree = vec![0usize; adj.len()];
    for edges in adj {
        for &v in edges {
            if v < indegree.len() {
                indegree[v] += 1;
            }
        }
    }

    let mut queue = VecDeque::new();
    for i in 0..adj.len() {
        if indegree[i] == 0 {
            queue.push_back(i);
        }
    }

    let mut layers = Vec::new();
    while !queue.is_empty() {
        let level_count = queue.len();
        let mut layer = Vec::with_capacity(level_count);
        for _ in 0..level_count {
            if let Some(u) = queue.pop_front() {
                layer.push(u);
                for &v in &adj[u] {
                    if v < indegree.len() {
                        indegree[v] -= 1;
                        if indegree[v] == 0 {
                            queue.push_back(v);
                        }
                    }
                }
            }
        }
        if !layer.is_empty() {
            layers.push(layer);
        }
    }
    layers
}

use std::collections::VecDeque;

pub fn topological_sort(adj: &[Vec<usize>]) -> Vec<usize> {
    let mut indegree = vec![0; adj.len()];
    for edges in adj {
        for &v in edges {
            indegree[v] += 1;
        }
    }

    let mut queue = VecDeque::new();
    for i in 0..adj.len() {
        if indegree[i] == 0 {
            queue.push_back(i);
        }
    }

    let mut order = Vec::new();
    while let Some(u) = queue.pop_front() {
        order.push(u);
        for &v in &adj[u] {
            indegree[v] -= 1;
            if indegree[v] == 0 {
                queue.push_back(v);
            }
        }
    }
    order
}

//! GPU-assisted topological sort (Kahn) using CUDA kernels.

use super::csr::Csr;

#[cfg(feature = "cuda")]
unsafe extern "C" {
    fn gpu_topo_indegree(row_ptr: *const i32, col_idx: *const i32, v: i32, indegree_out: *mut i32);
    fn gpu_topo_frontier(indegree: *const i32, removed: *const u8, v: i32, frontier_out: *mut u8, count_out: *mut i32);
    fn gpu_topo_remove_frontier(row_ptr: *const i32, col_idx: *const i32, v: i32, frontier: *const u8, indegree: *mut i32, removed: *mut u8);
}

#[cfg(feature = "cuda")]
pub fn indegree_gpu(csr: &Csr) -> Vec<i32> {
    let v = csr.vertex_count() as i32;
    let mut indegree = vec![0i32; csr.vertex_count()];
    unsafe {
        gpu_topo_indegree(csr.row_ptr.as_ptr(), csr.col_idx.as_ptr(), v, indegree.as_mut_ptr());
    }
    indegree
}

#[cfg(feature = "cuda")]
pub fn topological_sort_gpu(csr: &Csr) -> Vec<usize> {
    let v = csr.vertex_count() as i32;
    if v == 0 {
        return Vec::new();
    }
    let mut indegree = vec![0i32; v as usize];
    unsafe {
        gpu_topo_indegree(csr.row_ptr.as_ptr(), csr.col_idx.as_ptr(), v, indegree.as_mut_ptr());
    }
    let mut removed = vec![0u8; v as usize];
    let mut order = Vec::with_capacity(v as usize);
    loop {
        let mut frontier = vec![0u8; v as usize];
        let mut count = 0i32;
        unsafe {
            gpu_topo_frontier(indegree.as_ptr(), removed.as_ptr(), v, frontier.as_mut_ptr(), &mut count);
        }
        if count == 0 {
            break;
        }
        for (idx, &flag) in frontier.iter().enumerate() {
            if flag == 1 {
                order.push(idx);
            }
        }
        unsafe {
            gpu_topo_remove_frontier(csr.row_ptr.as_ptr(), csr.col_idx.as_ptr(), v, frontier.as_ptr(), indegree.as_mut_ptr(), removed.as_mut_ptr());
        }
        if order.len() == v as usize {
            break;
        }
    }
    order
}

