use std::collections::{HashMap, VecDeque};

pub struct LruCache<K: Eq + std::hash::Hash + Clone, V> {
    capacity: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + std::hash::Hash + Clone, V> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        Self { capacity, map: HashMap::new(), order: VecDeque::new() }
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.order.retain(|k| k != &key);
        }
        self.map.insert(key.clone(), value);
        self.order.push_back(key.clone());

        if self.order.len() > self.capacity {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            }
        }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.order.retain(|k| k != key);
            self.order.push_back(key.clone());
        }
        self.map.get(key)
    }
}

pub struct Node {
    pub marked: bool,
    pub children: Vec<usize>,
}

pub fn mark(nodes: &mut [Node], root: usize) {
    fn dfs(nodes: &mut [Node], i: usize) {
        if nodes[i].marked {
            return;
        }
        nodes[i].marked = true;
        let children = nodes[i].children.clone();
        for c in children {
            dfs(nodes, c);
        }
    }
    dfs(nodes, root);
}

pub fn sweep(nodes: &mut Vec<Node>) {
    nodes.retain(|n| n.marked);
}

