use std::cmp::Ordering;
use std::collections::BinaryHeap;

#[derive(Copy, Clone, Eq, PartialEq)]
struct Node {
    cost: u64,
    pos: usize,
}

impl Ord for Node {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for Node {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

pub fn a_star(adj: &[Vec<(usize, u64)>], start: usize, goal: usize, heuristic: fn(usize) -> u64) -> Option<u64> {
    let mut dist = vec![u64::MAX; adj.len()];
    let mut heap = BinaryHeap::new();

    dist[start] = 0;
    heap.push(Node { cost: heuristic(start), pos: start });

    while let Some(Node { pos, .. }) = heap.pop() {
        if pos == goal {
            return Some(dist[pos]);
        }
        for &(next, weight) in &adj[pos] {
            let next_cost = dist[pos] + weight;
            if next_cost < dist[next] {
                dist[next] = next_cost;
                heap.push(Node { cost: next_cost + heuristic(next), pos: next });
            }
        }
    }
    None
}

pub fn subsets<T: Clone>(set: &[T]) -> Vec<Vec<T>> {
    fn backtrack<T: Clone>(set: &[T], index: usize, current: &mut Vec<T>, result: &mut Vec<Vec<T>>) {
        if index == set.len() {
            result.push(current.clone());
            return;
        }
        backtrack(set, index + 1, current, result);
        current.push(set[index].clone());
        backtrack(set, index + 1, current, result);
        current.pop();
    }

    let mut result = Vec::new();
    backtrack(set, 0, &mut Vec::new(), &mut result);
    result
}

pub fn beam_search<S, Expand, Score>(
    initial: Vec<S>,
    beam_width: usize,
    depth: usize,
    mut expand: Expand,
    mut score: Score,
) -> Option<S>
where
    S: Clone,
    Expand: FnMut(&S, usize) -> Vec<S>,
    Score: FnMut(&S) -> i64,
{
    if initial.is_empty() || beam_width == 0 {
        return None;
    }

    let mut beam = initial;
    for level in 0..depth {
        let mut next = Vec::new();
        for state in &beam {
            next.extend(expand(state, level));
        }
        if next.is_empty() {
            break;
        }
        next.sort_by_key(|s| std::cmp::Reverse(score(s)));
        next.truncate(beam_width);
        beam = next;
    }

    beam.into_iter().max_by_key(|s| score(s))
}

pub fn branch_and_bound(weights: &[u64], capacity: u64) -> u64 {
    fn helper(weights: &[u64], i: usize, cap: u64) -> u64 {
        if i == weights.len() || cap == 0 {
            return 0;
        }
        if weights[i] > cap {
            helper(weights, i + 1, cap)
        } else {
            let include = weights[i] + helper(weights, i + 1, cap - weights[i]);
            let exclude = helper(weights, i + 1, cap);
            include.max(exclude)
        }
    }
    helper(weights, 0, capacity)
}

pub fn ddmin<T, F>(items: &[T], mut fails: F) -> Vec<T>
where
    T: Clone,
    F: FnMut(&[T]) -> bool,
{
    if items.is_empty() || !fails(items) {
        return Vec::new();
    }

    let mut current: Vec<T> = items.to_vec();
    let mut n = 2usize;

    while current.len() >= 2 {
        let chunk = current.len().div_ceil(n);
        let mut reduced = false;

        let mut i = 0usize;
        while i < current.len() {
            let end = usize::min(i + chunk, current.len());
            let mut candidate = Vec::with_capacity(current.len() - (end - i));
            candidate.extend_from_slice(&current[..i]);
            candidate.extend_from_slice(&current[end..]);

            if fails(&candidate) {
                current = candidate;
                n = usize::max(2, n - 1);
                reduced = true;
                break;
            }
            i = end;
        }

        if !reduced {
            if n >= current.len() {
                break;
            }
            n = usize::min(current.len(), n * 2);
        }
    }

    current
}

pub fn genetic_optimize<F>(mut population: Vec<u64>, fitness: F, generations: usize) -> u64
where F: Fn(u64) -> u64 {
    fn lcg(seed: &mut u64) -> u64 {
        *seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        *seed
    }

    let mut seed = 1u64;

    for _ in 0..generations {
        population.sort_by_key(|&x| fitness(x));
        population.truncate(population.len() / 2);

        while population.len() < 100 {
            let i = (lcg(&mut seed) as usize) % population.len();
            let j = (lcg(&mut seed) as usize) % population.len();
            let child = (population[i] + population[j]) / 2;
            population.push(child);
        }
    }

    *population.iter().max_by_key(|&&x| fitness(x)).unwrap()
}

