//! Equation (parallel tournament selection + crossover):
//!   parent_a = max(pop[ia], pop[ib]),  ia,ib ~ Uniform(0,POP)
//!   parent_b = max(pop[ic], pop[id]),  ic,id ~ Uniform(0,POP)
//!   child    = (parent_a + parent_b) / 2
//!   result   = max_i population[i]

